UPDATE important_contribution
SET status = 'approved',
approved_by = #{approvedBy},
approved_time = #{approvedTime}
WHERE id = #{id}

UPDATE important_contribution
SET status = 'rejected',
remark = #{remark}
WHERE id = #{id}

