SELECT contribution_type as contributionType, COUNT(*) as count
FROM important_contribution
WHERE tenant_id = #{tenantId}

    AND status = #{status}

GROUP BY contribution_type
ORDER BY count DESC

SELECT 
FROM important_contribution
WHERE tenant_id = #{tenantId}
AND user_id = #{userId}
AND status = 'approved'
AND create_time >= #{startTime}
AND create_time < #{endTime}
